package bookstore

import "sort"

// groupCosts[i] is the price, in cents, of a group of i distinct books.
var groupCosts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the price, in cents, of the basket with the biggest possible
// discount applied. Each book is identified by an integer from 1 to 5.
func Cost(books []int) int {
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}

	// Greedily form groups, always taking one copy of each of the most
	// in-demand titles.
	groupSizes := make([]int, 0, len(books))
	for {
		distinct := 0
		for _, c := range counts {
			if c > 0 {
				distinct++
			}
		}
		if distinct == 0 {
			break
		}
		sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })
		for i := 0; i < distinct; i++ {
			counts[i]--
		}
		groupSizes = append(groupSizes, distinct)
	}

	// Two groups of four cost 5120, while a group of five plus a group of
	// three cost 5160, so convert every such pair of groups.
	five, three := -1, -1
	for i, size := range groupSizes {
		switch {
		case size == 5 && three != -1:
			groupSizes[i], groupSizes[three] = 4, 4
			five, three = -1, -1
		case size == 3 && five != -1:
			groupSizes[i], groupSizes[five] = 4, 4
			five, three = -1, -1
		case size == 5:
			five = i
		case size == 3:
			three = i
		}
	}

	cost := 0
	for _, size := range groupSizes {
		cost += groupCosts[size]
	}
	return cost
}

